import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import org.apache.commons.cli.Option;
import org.apache.commons.cli.OptionGroup;
import org.apache.commons.cli.Options;
import org.junit.Test;

public class AddOptionsTests {

    @Test
    public void addOptionsAddsAllOptionsFromSource() {
        Options target = new Options();
        Options source = new Options();
        source.addOption(Option.builder("a").longOpt("alpha").desc("alpha option").build());
        source.addOption(Option.builder("b").longOpt("beta").desc("beta option").build());

        Options result = target.addOptions(source);

        assertSame(target, result);
        assertTrue(target.hasOption("a"));
        assertTrue(target.hasOption("b"));
        assertEquals(2, target.getOptions().size());
    }

    @Test
    public void addOptionsThrowsOnDuplicateFirstOptionAndDoesNotAddAnyLaterOptions() {
        Options target = new Options();
        target.addOption(Option.builder("a").desc("existing option").build());

        Options source = new Options();
        source.addOption(Option.builder("a").desc("duplicate option").build());
        source.addOption(Option.builder("b").desc("second option").build());

        try {
            target.addOptions(source);
        } catch (IllegalArgumentException ex) {
            assertEquals("Duplicate key: a", ex.getMessage());
        }

        assertTrue(target.hasOption("a"));
        assertFalse(target.hasOption("b"));
        assertEquals(1, target.getOptions().size());
    }

    @Test
    public void addOptionsStillChecksDuplicateForSingleElementSource() {
        Options target = new Options();
        target.addOption(Option.builder("x").desc("existing option").build());

        Options source = new Options();
        source.addOption(Option.builder("x").desc("duplicate single option").build());

        try {
            target.addOptions(source);
        } catch (IllegalArgumentException ex) {
            assertEquals("Duplicate key: x", ex.getMessage());
        }

        assertEquals(1, target.getOptions().size());
        assertTrue(target.hasOption("x"));
    }

    @Test
    public void addOptionsAddsOptionGroups() {
        Options target = new Options();
        Options source = new Options();

        OptionGroup group = new OptionGroup();
        group.addOption(Option.builder("g1").desc("group option 1").build());
        group.addOption(Option.builder("g2").desc("group option 2").build());
        source.addOptionGroup(group);

        Options result = target.addOptions(source);

        assertSame(target, result);
        assertTrue(target.getOptionGroup("g1") != null);
        assertTrue(target.getOptionGroup("g2") != null);
    }
}

