import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class AddOptionsTests {

    @Test
    public void addOptionsShouldAddAllOptionsAndGroupsAndReturnThis() {
        Options target = new Options();
        Options source = new Options();

        Option option1 = Option.builder("a").desc("first").build();
        Option option2 = Option.builder("b").desc("second").build();
        OptionGroup group = new OptionGroup();
        group.addOption(Option.builder("x").desc("group option").build());
        group.setRequired(true);

        source.addOption(option1);
        source.addOption(option2);
        source.addOptionGroup(group);

        Options returned = target.addOptions(source);

        assertTrue(returned == target);
        assertTrue(target.hasOption("a"));
        assertTrue(target.hasOption("b"));
        assertTrue(target.hasOption("x"));
        assertEquals(2, target.getOptions().size());
        assertEquals(1, target.getOptionGroups().size());
    }

    @Test
    public void addOptionsShouldAllowDuplicateWhenOnlySecondOptionConflicts() {
        Options target = new Options();
        target.addOption(Option.builder("a").desc("existing").build());

        Options source = new Options();
        source.addOption(Option.builder("b").desc("new first").build());
        source.addOption(Option.builder("a").desc("duplicate second").build());

        try {
            target.addOptions(source);
        } catch (IllegalArgumentException ex) {
            throw new AssertionError("Original method should not reject a duplicate that appears after the first source option", ex);
        }

        assertTrue(target.hasOption("b"));
        assertTrue(target.hasOption("a"));
        assertEquals("duplicate second", target.getOption("a").getDescription());
        assertEquals(2, target.getOptions().size());
    }

    @Test
    public void addOptionsShouldNotFailWhenDuplicateIsOnlyInLaterPositionAndShouldPreserveAllOptions() {
        Options target = new Options();
        target.addOption(Option.builder("base").desc("existing base").build());

        Options source = new Options();
        source.addOption(Option.builder("new1").desc("first added").build());
        source.addOption(Option.builder("base").desc("shadowed base").build());
        source.addOption(Option.builder("new2").desc("third added").build());

        target.addOptions(source);

        assertTrue(target.hasOption("new1"));
        assertTrue(target.hasOption("new2"));
        assertTrue(target.hasOption("base"));
        assertEquals("shadowed base", target.getOption("base").getDescription());
        assertEquals(3, target.getOptions().size());
    }

    @Test
    public void addOptionsShouldAddOptionGroupsEvenWhenNoOptionsArePresent() {
        Options target = new Options();
        Options source = new Options();

        OptionGroup group = new OptionGroup();
        group.addOption(Option.builder("g").desc("group only").build());
        source.addOptionGroup(group);

        target.addOptions(source);

        assertEquals(0, target.getOptions().size());
        assertEquals(1, target.getOptionGroups().size());
        assertTrue(target.hasOption("g"));
    }
}

