                .setIndent(4)
                .setMaxWidth(5)
                .get();

        CharSequence text = "12345";

        assertSame(text, style.pad(true, text));
    }

    @Test
    public void returnsOriginalTextWhenLengthExceedsMaxWidthByOne() {
        TextStyle style = TextStyle.builder()
                .setAlignment(TextStyle.Alignment.RIGHT)
                .setIndent(4)
                .setMaxWidth(5)
                .get();

        CharSequence text = "123456";

        assertSame(text, style.pad(false, text));
    }

    @Test
    public void leftAlignmentPadsIndentAndRestWhenIndentIsApplied() {
        TextStyle style = TextStyle.builder()
                .setAlignment(TextStyle.Alignment.LEFT)
                .setIndent(2)
                .setMaxWidth(8)
                .get();

        assertEquals("  abc   ", style.pad(true, "abc").toString());
    }

    @Test
    public void rightAlignmentPadsIndentAndRestWhenIndentIsApplied() {
        TextStyle style = TextStyle.builder()
                .setAlignment(TextStyle.Alignment.RIGHT)
                .setIndent(2)
                .setMaxWidth(8)
                .get();

        assertEquals("  ___abc", style.pad(true, "abc").toString().replace('_', ' '));
    }

