    public void rightAlignmentDoesNotApplyIndentWhenRemainingWidthIsNotGreaterThanIndent() {
        TextStyle style = TextStyle.builder()
                .setAlignment(TextStyle.Alignment.RIGHT)
                .setIndent(3)
                .setMaxWidth(6)
                .get();

        assertEquals("__abc", style.pad(true, "abc").toString().replace('_', ' '));
    }

    @Test
    public void centerAlignmentSplitsPaddingEvenly() {
        TextStyle style = TextStyle.builder()
                .setAlignment(TextStyle.Alignment.CENTER)
                .setIndent(2)
                .setMaxWidth(8)
                .get();

        assertEquals("  abc   ", style.pad(true, "abc").toString());
    }

