import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.lang.reflect.Method;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import org.junit.Test;

public class AdjustTableFormatTests {

    private static final class TestableTextHelpAppendable extends TextHelpAppendable {
        TestableTextHelpAppendable() {
            super(new StringBuilder());
        }

        TableDefinition adjust(final TableDefinition table) {
            return adjustTableFormat(table);
        }
    }

    @Test
    public void shouldNotRescaleWhenWidthsExactlyMatchAvailableWidth() {
        final TestableTextHelpAppendable helper = new TestableTextHelpAppendable();
        final TableDefinition table = TableDefinition.from(
            "caption",
            Arrays.asList(
                TextStyle.builder().setMaxWidth(20).setLeftPad(1).setIndent(0).get(),
                TextStyle.builder().setMaxWidth(20).setLeftPad(1).setIndent(0).get()
            ),
            Arrays.asList("H1", "H2"),
            Collections.singletonList(Arrays.asList("1234567890", "abcdefghij"))
        );

        final TableDefinition adjusted = helper.adjust(table);

        assertEquals(2, adjusted.columnTextStyles().size());
        assertEquals(10, adjusted.columnTextStyles().get(0).getMaxWidth());
        assertEquals(10, adjusted.columnTextStyles().get(1).getMaxWidth());
        assertEquals(2, adjusted.columnTextStyles().get(0).getLeftPad() + adjusted.columnTextStyles().get(1).getLeftPad());
    }

    @Test
    public void shouldRescaleWhenComputedWidthWouldExceedAvailableWidth() {
        final TestableTextHelpAppendable helper = new TestableTextHelpAppendable();
        final TableDefinition table = TableDefinition.from(
            "caption",
            Arrays.asList(
                TextStyle.builder().setMaxWidth(40).setLeftPad(1).setIndent(0).get(),
                TextStyle.builder().setMaxWidth(40).setLeftPad(1).setIndent(0).get()
            ),
            Arrays.asList("HeaderOne", "HeaderTwo"),
            Collections.singletonList(Arrays.asList("abcdefghijklmnopqrstuvwxyz", "01234567890123456789012345"))
        );

        final TableDefinition adjusted = helper.adjust(table);

        assertEquals(2, adjusted.columnTextStyles().size());
        assertTrue(adjusted.columnTextStyles().get(0).getMaxWidth() < 26);
        assertTrue(adjusted.columnTextStyles().get(1).getMaxWidth() < 26);
        assertTrue(adjusted.columnTextStyles().get(0).getMaxWidth() > 0);
        assertTrue(adjusted.columnTextStyles().get(1).getMaxWidth() > 0);
    }

    @Test
    public void shouldKeepNonScalableColumnWidthUnchangedWhenRescalingOccurs() {
        final TestableTextHelpAppendable helper = new TestableTextHelpAppendable();
        final TextStyle fixed = TextStyle.builder().setMaxWidth(3).setLeftPad(1).setIndent(0).setScalable(false).get();
        final TextStyle scalable = TextStyle.builder().setMaxWidth(50).setLeftPad(1).setIndent(0).get();
        final TableDefinition table = TableDefinition.from(
            "caption",
            Arrays.asList(fixed, scalable),
            Arrays.asList("Fixed", "Scalable"),
            Collections.singletonList(Arrays.asList("abc", "abcdefghijklmnopqrstuvwxyzabcdef"))
        );

        final TableDefinition adjusted = helper.adjust(table);

        assertEquals(2, adjusted.columnTextStyles().size());
        assertEquals(3, adjusted.columnTextStyles().get(0).getMaxWidth());
        assertTrue(adjusted.columnTextStyles().get(1).getMaxWidth() < 32);
        assertFalse(adjusted.columnTextStyles().get(1).isScalable());
    }

    @Test
    public void shouldExpandUnsetAndHeaderLimitedWidthsToFitHeaderAndCells() {
        final TestableTextHelpAppendable helper = new TestableTextHelpAppendable();
        final TableDefinition table = TableDefinition.from(
            "caption",
            Collections.singletonList(TextStyle.builder().setMaxWidth(TextStyle.UNSET_MAX_WIDTH).setLeftPad(1).setIndent(0).get()),
            Collections.singletonList("VeryLongHeader"),
            Collections.singletonList(Collections.singletonList("longercellvalue"))
        );

        final TableDefinition adjusted = helper.adjust(table);

        assertEquals(1, adjusted.columnTextStyles().size());
        assertEquals("VeryLongHeader".length(), adjusted.columnTextStyles().get(0).getMaxWidth());
        assertEquals("VeryLongHeader".length(), adjusted.columnTextStyles().get(0).getMinWidth());
    }

    @Test
    public void shouldThrowWhenRowsDoNotMatchColumnCount() {
        final TestableTextHelpAppendable helper = new TestableTextHelpAppendable();
        final TableDefinition table = TableDefinition.from(
            "caption",
            Collections.singletonList(TextStyle.builder().setMaxWidth(10).setLeftPad(1).setIndent(0).get()),
            Collections.singletonList("H1"),
            Collections.singletonList(Arrays.asList("value1", "value2"))
        );

        boolean thrown = false;
        try {
            helper.adjust(table);
        } catch (IndexOutOfBoundsException ex) {
            thrown = true;
        }
        assertTrue(thrown);
    }
}

