package org.apache.commons.cli.help;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;

import org.junit.Test;

public class IndexOfWrapTests {

    @Test
    public void testWidthLessThanOneThrowsException() {
        assertThrows(IllegalArgumentException.class, () -> TextHelpAppendable.indexOfWrap("abc", 0, 0));
        assertThrows(IllegalArgumentException.class, () -> TextHelpAppendable.indexOfWrap("abc", -1, 0));
    }

    @Test
    public void testReturnsBreakCharacterIndexWithinWidth() {
        CharSequence text = "ab\ncdef";
        assertEquals(2, TextHelpAppendable.indexOfWrap(text, 5, 0));
    }

    @Test
    public void testReturnsTextLengthWhenWrapBeyondEnd() {
        CharSequence text = "abc";
        assertEquals(3, TextHelpAppendable.indexOfWrap(text, 10, 0));
    }

    @Test
    public void testReturnsLastWhitespaceAtLimit() {
        CharSequence text = "abc defg";
        assertEquals(3, TextHelpAppendable.indexOfWrap(text, 4, 0));
    }

    @Test
    public void testMutantDetectedWhenWhitespaceIsExactlyAtStartPlusOne() {
        CharSequence text = "ab cdef";
        assertEquals(2, TextHelpAppendable.indexOfWrap(text, 3, 0));
    }

    @Test
    public void testNoWhitespaceBeforeLimitChopsAtLimitMinusOne() {
        CharSequence text = "abcdefg";
        assertEquals(3, TextHelpAppendable.indexOfWrap(text, 4, 0));
    }

    @Test
    public void testStartPositionOffsetIsHandled() {
        CharSequence text = "xx abcdef";
        assertEquals(2, TextHelpAppendable.indexOfWrap(text, 3, 0));
        assertEquals(5, TextHelpAppendable.indexOfWrap(text, 3, 2));
    }

    @Test
    public void testBoundaryAtTextEndWithStartPositionNearEnd() {
        CharSequence text = "abc def";
        assertEquals(7, TextHelpAppendable.indexOfWrap(text, 5, 2));
    }
}

