package org.apache.commons.cli;

import static org.junit.Assert.*;

import java.util.Collection;

import org.junit.Test;

public class AddOptionGroupTests {

    @Test
    public void testAddOptionGroupRequiredGroupMarksGroupAsRequiredAndRegistersOptions() {
        Options options = new Options();

        OptionGroup group = new OptionGroup();
        group.setRequired(true);

        Option optA = Option.builder("a").build();
        Option optB = Option.builder("b").build();
        group.addOption(optA);
        group.addOption(optB);

        Options returned = options.addOptionGroup(group);

        assertSame(options, returned);
        assertTrue(optA.isRequired() == false);
        assertTrue(optB.isRequired() == false);
        assertTrue(options.getOptions().contains(optA));
        assertTrue(options.getOptions().contains(optB));
        assertSame(group, options.getOptionGroup(optA));
        assertSame(group, options.getOptionGroup(optB));

        Collection<?> required = options.getRequiredOptions();
        assertTrue(required.contains(group));
        assertFalse(required.contains("a"));
        assertFalse(required.contains("b"));
    }

    @Test
    public void testAddOptionGroupNonRequiredGroupDoesNotAddGroupToRequiredOptions() {
        Options options = new Options();

        OptionGroup group = new OptionGroup();
        group.setRequired(false);

        Option optA = Option.builder("a").build();
        group.addOption(optA);

        options.addOptionGroup(group);

        Collection<?> required = options.getRequiredOptions();
        assertFalse(required.contains(group));
        assertFalse(required.contains("a"));
        assertSame(group, options.getOptionGroup(optA));
        assertFalse(optA.isRequired());
    }

    @Test
    public void testAddOptionGroupRemovesPreviouslyRequiredOptionKey() throws Exception {
        Options options = new Options();

        Option standalone = Option.builder("x").required().build();
        options.addOption(standalone);
        assertTrue(options.getRequiredOptions().contains("x"));

        OptionGroup group = new OptionGroup();
        group.setRequired(false);
        Option grouped = Option.builder("x").build();
        group.addOption(grouped);

        options.addOptionGroup(group);

        Collection<?> required = options.getRequiredOptions();
        assertFalse(required.contains("x"));
        assertSame(group, options.getOptionGroup(grouped));
        assertFalse(grouped.isRequired());
        assertTrue(options.getOptions().contains(grouped));
    }

    @Test
    public void testAddOptionGroupRejectsDuplicateOptionKeysInOptions() {
        Options options = new Options();

        Option existing = Option.builder("a").build();
        options.addOption(existing);

        OptionGroup group = new OptionGroup();
        group.setRequired(false);
        Option duplicate = Option.builder("a").build();
        group.addOption(duplicate);

        try {
            options.addOptionGroup(group);
            fail("Expected an exception for duplicate option key");
        } catch (Exception ex) {
            assertTrue(ex instanceof IllegalArgumentException);
        }
    }

    @Test
    public void testAddOptionGroupWithEmptyGroupHasNoSideEffectsExceptReturnValue() {
        Options options = new Options();

        OptionGroup group = new OptionGroup();
        group.setRequired(true);

        Options returned = options.addOptionGroup(group);

        assertSame(options, returned);
        assertTrue(options.getRequiredOptions().contains(group));
        assertTrue(options.getOptions().isEmpty());
    }
}
